arguments.command:
cd /tmp/scratchpad/main-wt && total=0; for b in rachel monica phoebe joey chandler ross; do n=$(git rev-list --all --grep='Friend-Message: 1' origin/friend/$b 2>/dev/null | wc -l); # rev-list grep maybe; better log
  n=$(git log --all --format='%H' --grep='Friend-Message: 1' origin/friend/$b | wc -l);
  echo "$b: $n"; total=$((total+n)); done; echo "total $total"
